/* Names (3DS system names, Mii names, group.ini name=) in the game's text font: one converter for every screen.
 * Plain C, no 3DS or game headers, so host tests build it (tests/name_text_tests.c).
 *
 * The font (HSD_SisLib_FontAtlas, 287 glyphs) has full-width ASCII, hiragana, katakana, some punctuation and about 25
 * kanji; port/3ds/name_glyphs.h (generated by tools/gen_name_glyphs.py) lists them. Accented Latin letters fold to
 * their base letter (é -> e, ß -> ss), half-width katakana to full-width; anything else shows as a full-width "？". */
#ifndef NAME_TEXT_H
#define NAME_TEXT_H
#include <stdint.h>

#define NAME_MAX_CHARS 10          /* a 3DS user name or Mii name: 10 UTF-16 units */
#define NAME_TEXT_QUESTION 0x8148  /* Shift-JIS "？" */

/* The next code point of a UTF-8 string, moving *s past it. An invalid or cut-off sequence gives U+FFFD and moves on
 * by one byte; the NUL gives 0 and does not move. */
uint32_t name_utf8_next(const char **s);
/* Write code point cp as UTF-8 into out (at least 4 bytes); returns the bytes written. */
int name_utf8_put(uint32_t cp, char *out);
/* A name made safe: valid UTF-8 (invalid bytes dropped), no control characters, at most max_chars characters, cut only
 * between characters, NUL-terminated within cap bytes (a character that would not fit is left out). Returns the byte
 * length. Every place that cuts a name uses this: never "%.Ns". */
int name_clean(const char *in, char *out, int cap, int max_chars);
/* UTF-16 (a 3DS user name or Mii name, up to `units` units or a 0) to a cleaned UTF-8 name (name_clean, max_chars). */
int name_from_utf16(const uint16_t *in, int units, char *out, int cap, int max_chars);
/* The game's text bytes for one code point: 1 byte (the ASCII the SIS text takes as it is) or 2 (Shift-JIS), written
 * to out; 0 when the character is dropped (a voicing mark on its own). Folded characters may give several. Returns the
 * bytes written; out needs 8 bytes. */
int name_char_to_game(uint32_t cp, char *out);
/* A whole UTF-8 name as SIS text bytes, stopping before a character that would not fit with the NUL. Returns the byte
 * length. */
int name_to_game(const char *utf8, char *out, int len);
/* The font atlas index for a non-ASCII code point (after folding; a fold to several letters gives the first), or the
 * index of "？" when the font has no such character. -1 for a dropped character. */
int name_to_atlas(uint32_t cp);
/* The font atlas index of a Shift-JIS code the font has, else -1. */
int name_sjis_to_atlas(unsigned sjis);

#endif
